{v:'VER',what:'the cook countdown grows at 4K: cooking a frag, COOKING over the operator is drawn about twice its 1080p size on a 4K screen',
 run:function(){
   if(!(window.__deploy&&window.__state&&window.__endRaid&&window.__frame&&window.__forceSize)) return 'SKIP: this fixture cannot deploy and draw';
   var bad=[], g, p, oFT=ctx.fillText, hit=null, s1, s4, d=(typeof DPR==='number'&&DPR>0)?DPR:1;
   function grab(){ var k; for(k=0;k<8;k++){ hit=null; p.cooking=true; p.cookKind='frag'; p.cookT=0.4; __frame(0.05); } return hit; }
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __forceSize(1920,1080);
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||!g.player||g.over) return 'SKIP: no live raid';
     p=g.player; g.ents.length=0; g.bagOpen=false; g.mapOpen=false;
     ctx.fillText=function(t,x,y){ if(String(t).indexOf('COOKING ')===0&&!hit){ var m=ctx.getTransform(), fm=(/([\d.]+)px/).exec(String(ctx.font)); hit={px:(fm?parseFloat(fm[1]):0)*m.d/d,ok:isFinite(x)&&isFinite(y)}; } return oFT.apply(this,arguments); };
     s1=grab();
     __forceSize(3840,2160); if(!(W>3000)) return 'SKIP: the canvas would not go to 4K';
     s4=grab();
     if(!s1||!s4) return 'SKIP: the cook countdown was not drawn';
     if(!s1.ok||!s4.ok) return 'SKIP: the countdown has no place on screen in this staging';
     if(s4.px<s1.px*1.7) bad.push('at 4K COOKING is '+s4.px.toFixed(1)+' px against '+s1.px.toFixed(1)+' px at 1080p');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ delete ctx.fillText; if(ctx.fillText!==oFT) ctx.fillText=oFT; try{ __forceSize(1920,1080); }catch(_f){} try{ var g2=__state(); if(g2){ g2.player.cooking=false; g2.player.cookKind=null; if(!g2.over){ g2.player.downed=false; __endRaid('abandon'); } } }catch(_e){} __topClear(); __cleanProfile(); }
   return bad.length?bad.join('; '):null; }},
